 add(24,19,[series('first','Первый набор измерений через ;','1;2;3',{signed:true}),series('second','Второй набор измерений через ;','2;4;6',{signed:true})],'r Pearson = Σ((x−x̄)(y−ȳ))/sqrt(Σ(x−x̄)²Σ(y−ȳ)²).','r',x=>{const a=mean(x.first),b=mean(x.second);return sum(x.first.map((v,i)=>(v-a)*(x.second[i]-b)))/Math.sqrt(sum(x.first.map(v=>(v-a)**2))*sum(x.second.map(v=>(v-b)**2)));},'Корреляция не означает согласие измерений: постоянное смещение и масштаб могут дать r=1.',1,x=>requireThat(x.first.length===x.second.length&&x.first.length>=2&&sd(x.first)>0&&sd(x.second)>0,'Нужны равные непостоянные массивы из хотя бы двух измерений.'));
