 const coordinateFields=()=>[lat('lat1','Широта точки 1, градусы',0),lon('lon1','Долгота точки 1, градусы',0),lat('lat2','Широта точки 2, градусы',0),lon('lon2','Долгота точки 2, градусы',90)];
 function spherical(x){const a=rad(x.lat1),b=rad(x.lat2),d=rad(x.lat2-x.lat1),l=rad(signedAngle(x.lon2-x.lon1));const h=Math.sin(d/2)**2+Math.cos(a)*Math.cos(b)*Math.sin(l/2)**2;return 6371*2*Math.atan2(Math.sqrt(Math.max(0,Math.min(1,h))),Math.sqrt(Math.max(0,1-h)));}
