 function simplePolygonArea(x){
  let points=x.x.map((v,i)=>[v,x.y[i]]);
  if(points.length>3&&points[0][0]===points.at(-1)[0]&&points[0][1]===points.at(-1)[1])points.pop();
  requireThat(points.length>=3&&points.length<=200,'Нужно от 3 до 200 вершин простого полигона.');
  requireThat(new Set(points.map(p=>p.join(';'))).size===points.length,'Повторные вершины не допускаются.');
  const cross=(a,b,c)=>(b[0]-a[0])*(c[1]-a[1])-(b[1]-a[1])*(c[0]-a[0]);
  const on=(a,b,c)=>cross(a,b,c)===0&&c[0]>=Math.min(a[0],b[0])&&c[0]<=Math.max(a[0],b[0])&&c[1]>=Math.min(a[1],b[1])&&c[1]<=Math.max(a[1],b[1]);
  const n=points.length;
  for(let i=0;i<n;i++){
   const a=points[i],b=points[(i+1)%n],previous=points[(i+n-1)%n];
   requireThat(!(cross(previous,a,b)===0&&((a[0]-previous[0])*(b[0]-a[0])+(a[1]-previous[1])*(b[1]-a[1]))<0),'Соседние рёбра накладываются.');
   for(let j=i+2;j<n;j++){
    if(i===0&&j===n-1)continue;
    const c=points[j],d=points[(j+1)%n],ab1=cross(a,b,c),ab2=cross(a,b,d),cd1=cross(c,d,a),cd2=cross(c,d,b);
    requireThat(!((Math.sign(ab1)*Math.sign(ab2)<0&&Math.sign(cd1)*Math.sign(cd2)<0)||on(a,b,c)||on(a,b,d)||on(c,d,a)||on(c,d,b)),'Самопересечение или касание несоседних рёбер.');
   }
  }
  const [ox,oy]=points[0],area=Math.abs(sum(points.map((p,i)=>{const q=points[(i+1)%n];return (p[0]-ox)*(q[1]-oy)-(q[0]-ox)*(p[1]-oy);}))/2);
  requireThat(area>0,'Вырожденный полигон: площадь равна нулю.');return area;
 }
